function buildGraph(n: number, edges: [number, number][]) {
  const adj: number[][] = Array.from({ length: n }, () => [])
  for (const [a, b] of edges) {
    adj[a].push(b)
    adj[b].push(a) // omit this line for a directed graph
  }
  return adj
}

