function numIslands(grid: string[][]): number {
  const rows = grid.length
  const cols = rows ? grid[0].length : 0
  const seen = new Set<string>()
  let islands = 0
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1' || seen.has(`${r},${c}`)) continue
      islands++
      // Explore the whole island with an explicit stack (DFS)
      const stack: [number, number][] = [[r, c]]
      seen.add(`${r},${c}`)
      while (stack.length) {
        const [y, x] = stack.pop()!
        for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const ny = y + dy
          const nx = x + dx
          const key = `${ny},${nx}`
          if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && grid[ny][nx] === '1' && !seen.has(key)) {
            seen.add(key)
            stack.push([ny, nx])
          }
        }
      }
    }
  }
  return islands
}

